/**
 * Station 1.5: Rekursive Algorithmen.
 * Alle Methoden sind static: Man ruft sie über den Klassennamen auf,
 * z. B. Algorithmen.ggT(84, 36). Ein Objekt braucht man dafür nicht.
 * Suche (Strg + F) nach "TODO". Die Platzhalter liefern absichtlich falsche Werte.
 */
public class Algorithmen {

   // ===== Aufgabe 1: Hin und zurück (fertig) =====
   public static void countdown(int n) {
      if (n == 0) {                    // Abbruchbedingung
         println("Start!");
      } else {
         println("hin " + n);
         countdown(n - 1);             // rekursiver Aufruf
         println("zurück " + n);
      }
   }

   // ===== Aufgabe 3: größter gemeinsamer Teiler nach Euklid (fertig) =====
   public static int ggT(int a, int b) {
      if (b == 0) {                    // Abbruchbedingung
         return a;
      }
      return ggT(b, a % b);            // rekursiver Aufruf mit kleineren Zahlen
   }

   // ===== Aufgabe 4: lineare Rekursion =====

   // Quersumme: quersumme(4711) = 4 + 7 + 1 + 1 = 13
   public static int quersumme(int n) {
      if (n < 10) {                    // Abbruchbedingung: einstellig
         return n;
      }
      return n % 10 + quersumme(n / 10);   // letzte Ziffer + Quersumme vom Rest
   }

   // Zahl n (n >= 0) in der Basis basis (2 bis 16) als Text: umrechnen(22, 2) = "10110"
   // Die Ziffer für einen Rest r liefert ziffern.charAt(r), z. B. ziffern.charAt(11) = 'B'.
   public static String umrechnen(int n, int basis) {
      String ziffern = "0123456789ABCDEF";
      if (n < basis) {                 // Abbruchbedingung: nur noch eine Ziffer
         return "" + ziffern.charAt(n);
      }
      return umrechnen(n / basis, basis) + ziffern.charAt(n % basis);   // Rest zuerst, letzte Ziffer hinten
   }

   // Text rückwärts: umdrehen("Regal") = "lageR"
   // Nützlich: s.length(), s.charAt(0), s.substring(1) (alles ab dem 2. Zeichen)
   public static String umdrehen(String s) {
      if (s.length() <= 1) {           // Abbruchbedingung: leer oder ein Zeichen
         return s;
      }
      return umdrehen(s.substring(1)) + s.charAt(0);   // Rest umgedreht, erstes Zeichen ans Ende
   }

   // ===== Aufgabe 5: verzweigte Rekursion =====

   // Zählt, wie oft fib aufgerufen wird. Das Hauptprogramm setzt ihn vorher auf 0.
   public static int aufrufe = 0;

   // Fibonacci-Zahlen 0, 1, 1, 2, 3, 5, 8, 13, …
   // fib(0) = 0, fib(1) = 1, fib(n) = fib(n - 1) + fib(n - 2)
   public static int fib(int n) {
      aufrufe++;                       // 5b
      if (n == 0) {                    // Abbruchbedingung 1
         return 0;
      }
      if (n == 1) {                    // Abbruchbedingung 2
         return 1;
      }
      return fib(n - 1) + fib(n - 2);  // zwei rekursive Aufrufe
   }
}

/**
 * Aufgabe 2: Drei Fassungen von countdown, die nicht enden.
 * Starte sie einzeln im Hauptprogramm und beobachte die Ausgabe.
 * Echtes Java bricht nach einigen Tausend wartenden Aufrufen mit einem
 * StackOverflowError ab. Die Online-IDE hat keine solche Grenze, deshalb
 * übernimmt das hier auf der Website der Wächter.
 */
public class Experiment {

   // Fassung A
   public static void fassungA(int n) {
      println(n);
      fassungA(n - 1);
   }

   // Fassung B
   // TODO 2 (Aufgabe 2c): Ändere nur die Abbruchbedingung,
   // sodass die Methode für jede Startzahl endet.
   public static void fassungB(int n) {
      if (n <= 0) {
         println("Start!");
      } else {
         println(n);
         fassungB(n - 2);
      }
   }

   // Fassung C
   public static void fassungC(int n) {
      if (n == 0) {
         println("Start!");
      } else {
         println(n);
         fassungC(n);
      }
   }
}

/**
 * Aufgabe 6: Der Tresor. Diese Klasse ist fertig, du brauchst nur den Code.
 * Die Nachricht ist mit dem Caesar-Verfahren verschlüsselt (Klasse 11).
 * Der Schlüssel ist der Wert des Codes im Zweiersystem.
 * Auch hier arbeiten zwei rekursive Methoden: wert und entschluesseln.
 */
public class Tresor {
   private String geheim = "GERFBE BSSRA! HZ ERXHEFVBA MH IREFGRURA, ZHFFG QH MHREFG ERXHEFVBA IREFGRURA.";
   private String abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

   public void oeffnen(String code) {
      String text = entschluesseln(geheim, wert(code) % 26);
      println("Code " + code + ":");
      println(text);
      if (!text.startsWith("TRESOR OFFEN")) {
         println("Der Tresor bleibt zu. Prüfe die Zwischenwerte der vier Schritte!");
      }
   }

   // Wert einer Ziffernfolge im Zweiersystem: wert("1101") = 2 * wert("110") + 1
   public int wert(String ziffern) {
      if (ziffern.length() == 0) {
         return 0;
      }
      int letzte = 0;
      if (ziffern.endsWith("1")) {
         letzte = 1;
      }
      return 2 * wert(ziffern.substring(0, ziffern.length() - 1)) + letzte;
   }

   // Verschiebt jeden Großbuchstaben um k Stellen im Alphabet zurück, Zeichen für Zeichen
   public String entschluesseln(String text, int k) {
      if (text.length() == 0) {
         return "";
      }
      String erstes = text.substring(0, 1);
      int pos = abc.indexOf(erstes);
      if (pos >= 0) {
         erstes = abc.substring((pos - k + 26) % 26, (pos - k + 26) % 26 + 1);
      }
      return erstes + entschluesseln(text.substring(1), k);
   }
}

/**
 * Selbsttest der rekursiven Algorithmen. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class AlgorithmenTest {

   @Test
   public void quersummeEinstellig() {
      Assertions.assertEquals(7, Algorithmen.quersumme(7), "quersumme(7): Eine einstellige Zahl ist ihre eigene Quersumme.");
      Assertions.assertEquals(0, Algorithmen.quersumme(0), "quersumme(0) muss 0 sein.");
   }

   @Test
   public void quersummeMehrstellig() {
      Assertions.assertEquals(13, Algorithmen.quersumme(4711), "quersumme(4711) = 4 + 7 + 1 + 1 = 13");
      Assertions.assertEquals(1, Algorithmen.quersumme(1000), "quersumme(1000) = 1");
      Assertions.assertEquals(22, Algorithmen.quersumme(1597), "quersumme(1597) = 22");
   }

   @Test
   public void umrechnenBinaer() {
      Assertions.assertEquals("10110", Algorithmen.umrechnen(22, 2), "umrechnen(22, 2) muss \"10110\" sein.");
      Assertions.assertEquals("1", Algorithmen.umrechnen(1, 2), "umrechnen(1, 2) muss \"1\" sein.");
      Assertions.assertEquals("0", Algorithmen.umrechnen(0, 2), "umrechnen(0, 2) muss \"0\" sein.");
   }

   @Test
   public void umrechnenAndereBasis() {
      Assertions.assertEquals("211", Algorithmen.umrechnen(22, 3), "umrechnen(22, 3) muss \"211\" sein.");
      Assertions.assertEquals("FF", Algorithmen.umrechnen(255, 16), "umrechnen(255, 16) muss \"FF\" sein.");
      Assertions.assertEquals("2026", Algorithmen.umrechnen(2026, 10), "umrechnen(2026, 10) muss \"2026\" sein.");
   }

   @Test
   public void umdrehenKurz() {
      Assertions.assertEquals("", Algorithmen.umdrehen(""), "umdrehen(\"\") muss \"\" sein.");
      Assertions.assertEquals("a", Algorithmen.umdrehen("a"), "umdrehen(\"a\") muss \"a\" sein.");
   }

   @Test
   public void umdrehenLang() {
      Assertions.assertEquals("lageR", Algorithmen.umdrehen("Regal"), "umdrehen(\"Regal\") muss \"lageR\" sein.");
      Assertions.assertEquals("01101", Algorithmen.umdrehen("10110"), "umdrehen(\"10110\") muss \"01101\" sein.");
   }

   @Test
   public void fibAnfang() {
      Assertions.assertEquals(0, Algorithmen.fib(0), "fib(0) muss 0 sein.");
      Assertions.assertEquals(1, Algorithmen.fib(1), "fib(1) muss 1 sein.");
      Assertions.assertEquals(1, Algorithmen.fib(2), "fib(2) = fib(1) + fib(0) = 1");
   }

   @Test
   public void fibWeiter() {
      Assertions.assertEquals(55, Algorithmen.fib(10), "fib(10) muss 55 sein.");
      Assertions.assertEquals(1597, Algorithmen.fib(17), "fib(17) muss 1597 sein.");
   }

   @Test
   public void fibAufrufe() {
      Algorithmen.aufrufe = 0;
      Algorithmen.fib(5);
      Assertions.assertEquals(15, Algorithmen.aufrufe, "fib(5) ruft fib insgesamt 15-mal auf (den ersten Aufruf mitgezählt).");
      Algorithmen.aufrufe = 0;
      Algorithmen.fib(10);
      Assertions.assertEquals(177, Algorithmen.aufrufe, "fib(10) ruft fib insgesamt 177-mal auf.");
   }
}
